    zh: "偵察小組在河對岸、TAI 1 之內辨識出四個熱訊號。小型無人機的電池即將耗盡，因此在進一步偵察之前就被迫返航。偵察小組回報，還要二十分鐘才能再放飛另一架無人機。"
