    zh: "攻擊矩陣將<strong>攻擊型無人機</strong>列為對付工兵小組的第一順位手段。它同時也是唯一可以射擊的兵力：該小組位於橋上，也就是火力限制區之內，區內禁止使用會造成彈坑的彈藥。"
